<?php
// Shared read models for the three-step upload workflow. No posting on GET.
function os_category($r){if($r['errors']||$r['action']==='Missing from covering export')return 'checking';if($r['action']==='Excluded — not registered')return 'unregistered';if(in_array($r['action'],['Duplicate — skip','Unchanged'],true))return 'unchanged';return 'update';}
function os_effect($r){if($r['errors'])return 'No posting · resolve validation';$qty=array_sum($r['totals']);return match($r['action']){'Reserve'=>'Reserve '.$qty.' pcs · physical 0','Dispatch / post'=>'−'.$qty.' pcs · first dispatch','Cancel / release'=>'Release reservation · physical 0','Duplicate — skip'=>'Skip · no new record','Excluded — not registered'=>'No entry / stock change','Missing from covering export'=>'Keep previous status · follow up','Cancelled after posting — review receipt/reversal'=>'No automatic stock return',default=>'No new physical movement'};}
function os_counts($rows){$n=['update'=>0,'unchanged'=>0,'unregistered'=>0,'checking'=>0];foreach($rows as $r)$n[os_category($r)]++;return $n;}
function os_exception_key($pl,$shop,$order){return 'source-'.hash('sha256',json_encode([$pl,$shop,(string)$order]));}
function os_exception_states(){ $states=[];$users=[];foreach(db()->query('SELECT id,name FROM users') as $user)$users[$user['id']]=$user['name'];foreach(db()->query("SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE event_type IN ('Unregistered dispatch detected','Unregistered dispatch resolved') ORDER BY e.id") as $e){$d=json_decode($e['details_json'],true);if(!$d||empty($d['key']))continue;if($e['event_type']==='Unregistered dispatch resolved'){if(isset($states[$d['key']]))$states[$d['key']]['resolved']=true;continue;}$d['event_id']=$e['id'];$d['created_at']=$e['created_at'];$d['upload_id']=$e['upload_id'];$d['owner_name']=$users[$d['owner_id']??0]??$e['actor'];$d['resolved']=false;$states[$d['key']]=$d;}return $states;}
function os_open_exceptions($platform=''){$rows=[];foreach(os_exception_states() as $d){if($d['resolved']||($platform!==''&&$d['platform']!==$platform))continue;$o=om_find($d['platform'],$d['shop'],$d['order']);if($o&&$o['posting']==='Posted')continue;$rows[]=$d;}usort($rows,fn($a,$b)=>$b['event_id']<=>$a['event_id']);return $rows;}
function os_note_excluded($b,$r){if(!in_array($r['status'],['Shipped','Delivered','Completed'],true))return;$key=os_exception_key($b['platform'],$b['shop'],$r['order']);static $known=null;if($known===null)$known=os_exception_states();$old=$known[$key]??null;if($old&&($old['snapshot']??'')>=$b['meta']['snapshot'])return;om_event(null,$b['id'],'Unregistered dispatch detected',['key'=>$key,'platform'=>$b['platform'],'shop'=>$b['shop'],'order'=>(string)$r['order'],'status'=>$r['status'],'snapshot'=>$b['meta']['snapshot'],'owner_id'=>$b['created_by'],'stock_changed'=>false]);$known[$key]=['snapshot'=>$b['meta']['snapshot']];}
function os_resolve_exception($key,$reason){om_require();$reason=process_reason($reason);$found=null;foreach(os_open_exceptions() as $r)if(hash_equals($r['key'],(string)$key)){$found=$r;break;}if(!$found)throw new Exception('Exception is already resolved or no longer open.');om_event(null,$found['upload_id'],'Unregistered dispatch resolved',['key'=>$key,'reason'=>$reason,'order'=>$found['order'],'stock_changed'=>false]);audit('Resolve unregistered dispatch','Order Monitoring',$found['order'],$reason.'; no stock changed.');return $found['platform'];}
function os_exception_report($input){$rows=[];foreach(os_open_exceptions(in_array($input['platform']??'',['Shopee','Lazada','TikTok'],true)?$input['platform']:'') as $r)$rows[]=[$r['platform'],$r['shop'],(string)$r['order'],$r['status'],$r['snapshot'],$r['upload_id'],$r['owner_name'],'Needs checking · no automatic posting'];return ['title'=>'Unregistered Dispatch Exceptions','headers'=>['Platform','Shop','Order ID','Source Status','Export Snapshot','Source Upload','Responsible User','Resolution'],'rows'=>$rows,'summary'=>[],'links'=>[],'filters'=>$input,'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name'],'notes'=>['Source-file exception only. No order registration or stock posting is created.']];}
function os_validation_report($b){$rows=$b['status']==='Review'?om_plan($b)['orders']:(json_decode($b['result_json']??'{}',true)['validation']??[]);$out=[];foreach($rows as $r)$out[]=[(string)$r['order'],$r['order_record']['platform_status']??'Not registered',$r['status'],os_category($r),$r['action'],array_sum($r['totals']),os_effect($r),implode(' · ',$r['errors'])];return ['title'=>'Order Upload Validation #'.$b['id'],'headers'=>['Order ID','Previous Status','Uploaded Status','Category','Decision','Product Units','Inventory Effect','Validation'],'rows'=>$out];}
